, 'BASIC'
, (SELECT COUNT(*) FROM PDS_FILE k WHERE k.pds_id = #{pdsId})
, #{createUserId}
, #{createdAt}
, #{changedAt}
)

mapper.update:
UPDATE PDS
SET title             = #{title}
, title_no_space    = #{titleNoSpace}
, substance         = #{substance}
, attach_file_count = (
SELECT COUNT(*)
FROM PDS_FILE k
WHERE k.pds_id = #{pdsId}
)
, changed_at        = CURRENT_TIMESTAMP
WHERE pds_id = #{pdsId}

UPDATE PDS
SET attach_file_count = (
SELECT COUNT(*)
FROM PDS_FILE k
WHERE k.pds_id = #{pdsId}
)
, changed_at = CURRENT_TIMESTAMP
WHERE pds_id = #{pdsId}

mapper.select:
SELECT z.*
FROM PDS z


    AND z.location = 'BASIC'

ORDER BY z.created_at DESC
LIMIT #{rowsPerPage}
OFFSET #{pageNumber} * #{rowsPerPage}

